    getAvailability: {
        parameters: {
            query: {
                companyId: components["parameters"]["CompanyIdQuery"];
                masterId: components["parameters"]["MasterIdQuery"];
                /** @description Одна услуга. Нужен либо он, либо serviceIds; при обоих serviceIds[0] обязан совпадать с ним. */
                serviceId?: components["parameters"]["ServiceIdQuery"];
                /**
                 * @description Состав визита, 1..5 без повторов. Повторяется на каждый идентификатор
                 *     (serviceIds=a&serviceIds=b), НЕ в форме serviceIds[]=a.
                 */
                serviceIds?: components["parameters"]["ServiceIdsQuery"];
                /** @description Начало диапазона. Не раньше «сегодня−1». */
                from: string;
                /** @description Конец диапазона. Не раньше `from`; диапазон не более 31 дня. */
                to: string;
                /** @description Просьба включить режим персонала. Учитывается только для персонала этой компании и SuperAdmin. */
                manual?: boolean;
                /**
                 * @description НОВЫЙ в цикле 10. Просьба показать сутки целиком (игнорируя график и перерывы).
                 *     Действует ТОЛЬКО вместе с `manual=true` и ТОЛЬКО для персонала этой компании.
                 *     `extendedHours=true` без `manual=true` не даёт ничего никому.
                 */
                extendedHours?: boolean;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Состояние дней диапазона */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["AvailabilityDto"];
                };
            };
            400: components["responses"]["BadRequestText"];
            404: components["responses"]["NotFoundText"];
            429: components["responses"]["TooManyRequests"];
        };
    };
