    uploadCompanyPhoto: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description JPEG / PNG / WEBP, не больше 5 МБ.
                     */
                    file: string;
                };
            };
        };
        responses: {
            /** @description Такая фотография уже была загружена — возвращается существующая */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CompanyPhotoDto"];
                };
            };
            /** @description Фотография загружена */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CompanyPhotoDto"];
                };
            };
            /**
             * @description Голая строка. Возможные тексты:
             *       «В галерее салона может быть не больше 10 фотографий» (единственный новый, по-русски);
             *       File is required; Image is too large — the limit is 5 MB;
             *       Unsupported image type — use JPEG, PNG or WEBP;
             *       Image dimensions are too large — try a smaller image.;
             *       File is not a valid image; Server storage is full — try again later.
             *     Английские тексты общие для всех точек загрузки продукта и переводятся на фронте
             *     (utils/uploadError.ts) — второго словаря ошибок загрузки не заводим.
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            401: components["responses"]["UnauthorizedEmpty"];
            403: components["responses"]["ForbiddenEmpty"];
            404: components["responses"]["NotFoundEmpty"];
            /** @description Тело больше RequestSizeLimit (5 МБ) */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            429: components["responses"]["TooManyRequests"];
        };
    };
